static int run_gen(void) {
    source_pick pick;
    const char *types_out = "/app/lagpipe/synctab_out/layout.tbl";
    const char *tag_out = "/app/lagpipe/synctab_out/procance.tag";
    const char *guard_out = "/app/lagpipe/synctab_out/offline_guard.ok";
    FILE *fp;

    /* A stale guard must never make a failed synchronization look successful. */
    unlink(guard_out);
    unlink(types_out);
    unlink(tag_out);

    if (choose_layout(&pick) != 0 || pick.from_bundle) {
        fprintf(stderr, "imprint: live layout pick failed\n");
        return 1;
    }
    if (write_types_tab(pick.layout_path, types_out, pick.tag_value) != 0) {
        fprintf(stderr, "imprint: types write failed\n");
        unlink(types_out);
        return 1;
    }

    fp = fopen(tag_out, "w");
    if (!fp) {
        perror("imprint: procance.tag");
        unlink(types_out);
        return 1;
    }
    fprintf(fp, "%s\n", pick.tag_value);
    if (fclose(fp) != 0) {
        unlink(types_out);
        unlink(tag_out);
        return 1;
    }

    if (rebuild_binary() != 0) {
        fprintf(stderr, "imprint: rebuild failed\n");
        unlink(types_out);
        unlink(tag_out);
        return 1;
    }

    fp = fopen(guard_out, "w");
    if (!fp) {
        perror("imprint: offline_guard.ok");
        unlink(types_out);
        unlink(tag_out);
        return 1;
    }
    fputs("1\n", fp);
    if (fclose(fp) != 0) {
        unlink(guard_out);
        unlink(types_out);
        unlink(tag_out);
        return 1;
    }
    return 0;
}

